mapper.select:

where topic_id = #{topicId}
order by id asc
for update nowait

where and chapter_id in
#{chapterId}
order by id asc

mapper.update:
update merchant_chapter_offer
set status = 0, update_time = now()
where id = #{id}

mapper.select:
select o.id, o.topic_id, o.chapter_id, o.merchant_id, o.perk_id, o.terms_mode, o.payer_club_id, o.per_head_fee, o.quota_total, o.quota_used, o.valid_end, o.status, o.withdraw_reason, o.withdraw_required, o.replacement_of_offer_id, o.create_by, o.create_time, o.update_by, o.update_time, t.name as topic_name, t.lifecycle as topic_lifecycle, c.name as chapter_name, c.terms_mode as chapter_terms_mode, c.max_per_head_fee as chapter_max_per_head_fee, c.perk_min_value as chapter_perk_min_value, c.max_merchant as chapter_max_merchant, m.nickname as merchant_name, p.name as perk_name, p.retail_value as perk_retail_value, mm.name as mms_name, mm.status as mms_status, mm.business_license as business_license, mm.phone as mms_phone, mm.address as mms_address, mm.capacity as mms_capacity, (select COALESCE(sum(o2.quota_used), 0) from merchant_chapter_offer o2 where o2.merchant_id = o.merchant_id and o2.terms_mode = 'PERK' and (o2.status = 1 or o2.quota_used > 0)) as merchant_perk_used, (select COALESCE(sum(o2.quota_total), 0) from merchant_chapter_offer o2 where o2.merchant_id = o.merchant_id and o2.terms_mode = 'PERK' and (o2.status = 1 or o2.quota_used > 0)) as merchant_perk_total, (select COALESCE(sum(case mp.entry_type when 'ACCRUAL' then 1 when 'REVERSAL' then -1 else 0 end), 0) from merchant_payable mp where mp.merchant_member_id = o.merchant_id) as merchant_revshare_count from merchant_chapter_offer o left join cms_topic t on t.id = o.topic_id left join cms_topic_chapter c on c.id = o.chapter_id left join ums_member m on m.id = o.merchant_id left join coop_perk p on p.id = o.perk_id left join mms_merchant mm on mm.id = (select max(m3.id) from mms_merchant m3 where m3.member_id = o.merchant_id and m3.del_flag = 0)
and o.topic_id = #{topicId} and o.status = #{status}
order by o.topic_id desc, c.sort_id asc, o.chapter_id asc, o.create_time desc
